// FUN_00121de0
u32 h_campRequestMenuTransition(KwlnTask* task, u32 command)
{
    CampMenuWork* work;
    u32 timer;

    work = task->workData;
    switch (command)
    {
    case 0:
        work->state = 11;
        break;
    case 1:
        switch (work->timer)
        {
        case 0:
            work->state = 1;
            break;
        case 3:
            work->state = 9;
            break;
        case 4:
        case 6:
        case 7:
        case 8:
        case 9:
        case 11:
        case 12:
        case 13:
        case 15:
        case 16:
            work->state = 9;
            break;
        case 5:
            work->state = 9;
            break;
        }
        break;
    case 2:
        switch (work->timer)
        {
        case 0:
            work->state = 1;
            break;
        case 1:
        case 2:
            break;
        case 3:
            work->state = 7;
            break;
        case 4:
        case 6:
        case 7:
        case 8:
        case 9:
        case 13:
            work->state = 9;
            break;
        case 5:
        case 10:
        case 11:
        case 12:
            break;
        }
        break;
    case 3:
        switch (work->timer)
        {
        case 0:
        case 1:
            break;
        case 2:
            work->state = 5;
            break;
        case 3:
        case 4:
        case 5:
        case 6:
        case 7:
        case 8:
        case 9:
        case 10:
        case 11:
        case 12:
        case 13:
            break;
        }
        break;
    case 4:
    case 5:
    case 6:
    case 7:
    case 8:
    case 15:
    case 16:
        switch (work->timer)
        {
        case 0:
            break;
        case 1:
            work->state = 11;
            break;
        case 2:
            work->state = 11;
            break;
        case 3:
        case 4:
        case 5:
        case 6:
        case 7:
        case 8:
        case 9:
        case 10:
        case 11:
        case 12:
        case 13:
            break;
        }
        break;
    case 9:
        switch (work->timer)
        {
        case 0:
            break;
        case 1:
            work->state = 13;
            break;
        case 2:
        case 3:
        case 4:
        case 5:
        case 6:
        case 7:
        case 8:
        case 9:
        case 10:
        case 11:
        case 12:
        case 13:
            break;
        }
        break;
    case 13:
        switch (work->timer)
        {
        case 0:
            break;
        case 1:
            work->state = 13;
            break;
        case 2:
        case 3:
        case 4:
        case 5:
        case 6:
        case 7:
        case 8:
        case 9:
        case 10:
        case 11:
        case 12:
        case 13:
            break;
        }
        break;
    }
    work->timer = command;
    return 1;
}

// FUN_00121ff0 NONMATCHING
void* h_campUpdatePanelTransition(KwlnTask* task)
{
    CampPanelTransitionWork* work;
    CampVec2 pos;

    work = task->workData;
    switch (work->state) {
    case 0:
        if (work->transitionComplete != 0) {
            pos.x = 30.0f;
            pos.y = 219.0f;
            h_campStatusDrawScreen_typed(pos, pos, 100.0f, work->drawId, 1, 0, 0);
        }
        break;
    case 1:
        work->state = 2;
        work->timer = 0;
        break;
    case 2:
        work->timer++;
        if (work->timer == 0x15) {
            work->state = 0;
            pos.x = 30.0f;
            pos.y = 219.0f;
            h_campStatusDrawScreen_typed(pos, pos, 100.0f, work->drawId, 0, work->timer, 0);
            work->transitionComplete = 1;
        }
        break;
    case 3:
        pos.x = 30.0f;
        pos.y = 219.0f;
        h_campStatusDrawScreen_typed(pos, pos, 100.0f, work->drawId, 1, 0, 0);
        work->state = 4;
        break;
    case 4:
        pos.x = 30.0f;
        pos.y = 219.0f;
        h_campStatusDrawScreen_typed(pos, pos, 100.0f, work->drawId, 1, 0, 0);
        work->state = 0;
        work->transitionComplete = 1;
        break;
    case 5:
        pos.x = 30.0f;
        pos.y = 219.0f;
        h_campStatusDrawScreen_typed(pos, pos, 100.0f, work->drawId, 1, 0, 0);
        work->state = 6;
        work->timer = 0;
        break;
    case 6:
    {
        s32 timer;
        s32 drawTimer;
        s32 fade;

        work->timer++;
        timer = work->timer;
        if (timer == 8) {
            work->transitionComplete = 0;
            work->state = 0;
        }
        drawTimer = ((CampPanelTransitionWork*)work)->timer;
        pos.x = 30.0f - (f32)((drawTimer * 500) / 8);
        pos.y = 219.0f;
        fade = (drawTimer * 255) / 8;
        h_campStatusDrawScreen_typed(pos, pos, 100.0f, work->drawId, 1, 0, fade);
        break;
    }
    case 7:
        work->timer = 0;
        work->state = 8;
        break;
    case 8:
    {
        s32 timer;
        s32 drawTimer;
        s32 fade;

        work->timer++;
        timer = work->timer;
        if (timer == 8) {
            work->transitionComplete = 1;
            work->state = 0;
        }
        drawTimer = ((CampPanelTransitionWork*)work)->timer;
        pos.x = 30.0f - (f32)(500 - (drawTimer * 500) / 8);
        pos.y = 219.0f;
        fade = 255 - (drawTimer * 255) / 8;
        h_campStatusDrawScreen_typed(pos, pos, 100.0f, work->drawId, 1, 0, fade);
        break;
    }
    case 9:
        work->state = 10;
        work->timer = 0;
        break;
    case 10:
    {
        s32 timer;
        s32 drawTimer;
        s32 fade;

        work->timer++;
        timer = work->timer;
        if (timer == 0x14) {
            work->transitionComplete = 1;
            work->state = 0;
        }
        drawTimer = ((CampPanelTransitionWork*)work)->timer;
        pos.x = 30.0f;
        pos.y = 219.0f;
        fade = 255 - (drawTimer * 255) / 0x14;
        h_campStatusDrawScreen_typed(pos, pos, 100.0f, work->drawId, 1, 0, fade);
        break;
    }
    case 11:
        if (work->transitionComplete == 0) {
            work->state = 0;
            break;
        }
        pos.x = 30.0f;
        pos.y = 219.0f;
        h_campStatusDrawScreen_typed(pos, pos, 100.0f, work->drawId, 1, 0, 0);
        work->timer = 0;
        work->state = 12;
        break;
    case 12:
    {
        s32 timer;
        s32 drawTimer;
        s32 fade;

        work->timer++;
        timer = work->timer;
        if (timer == 0xa) {
            work->transitionComplete = 0;
            work->state = 0;
        }
        drawTimer = ((CampPanelTransitionWork*)work)->timer;
        pos.x = 30.0f;
        pos.y = 219.0f;
        fade = (drawTimer * 255) / 0xa;
        h_campStatusDrawScreen_typed(pos, pos, 100.0f, work->drawId, 1, 0, fade);
        break;
    }
    case 13:
        if (work->transitionComplete == 0) {
            work->state = 0;
            break;
        }
        pos.x = 30.0f;
        pos.y = 219.0f;
        h_campStatusDrawScreen_typed(pos, pos, 100.0f, work->drawId, 1, 0, 0);
        work->timer = 0;
        work->state = 14;
        break;
    case 14:
    {
        s32 timer;
        CampVec2 other;

        work->timer++;
        timer = work->timer;
        if (timer == 8) {
            work->transitionComplete = 0;
            work->state = 0;
            break;
        }
        if (timer < 3) {
            pos.x = 30.0f;
        } else {
            pos.x = 30.0f + (f32)(((timer - 3) * 84) / 5);
        }
        pos.y = 219.0f;
        other.x = 30.0f;
        other.y = 219.0f;
        h_campStatusDrawScreen_typed(pos, other, 100.0f, work->drawId, 1, 0, 0);
        break;
    }
    }
    return KWLNTASK_CONTINUE;
}
