/*
 * Camp's list renderer uses a 0x44-byte record.  The animation setup code
 * fills the interpolation fields at 0x28..0x34; these callbacks consume the
 * settled position, sprite scale, and alpha fields below.
 */
typedef struct CampMainDrawItem
{
    u32 owner;             /* 0x00 */
    u32 active;            /* 0x04 */
    void* resource0;       /* 0x08 */
    void* resource1;       /* 0x0c */
    void* resource2;       /* 0x10 */
    void* resource3;       /* 0x14 */
    u32 progress;          /* 0x18 */
    u32 startFrame;        /* 0x1c */
    u32 endFrame;          /* 0x20 */
    f32 spriteScale;       /* 0x24 */
    f32 startX;            /* 0x28 */
    f32 startY;            /* 0x2c */
    f32 scrollX;           /* 0x30 */
    f32 scrollY;           /* 0x34 */
    f32 x;                 /* 0x38 */
    f32 y;                 /* 0x3c */
    u32 alpha;             /* 0x40 */
} CampMainDrawItem;

/* The sprite list node allocated by FUN_001158b0. */
typedef struct CampMainSpriteNode
{
    void* next;            /* 0x00 */
    void* previous;        /* 0x04 */
    void* resource;        /* 0x08 */
    s32 frame;             /* 0x0c */
    f32 x;                 /* 0x10 */
    f32 y;                 /* 0x14 */
    u8 alpha;              /* 0x18 */
    u8 reserved19[0x0f];   /* 0x19..0x27 */
    u16 reserved28;        /* 0x28 */
    u16 rotation;          /* 0x2a */
    f32 spriteScale;       /* 0x2c */
} CampMainSpriteNode;

