        value = FUN_0016c4f0(statValue) & 0xffff;
        rank = value > 99;
        if (rank != 0) {
            campDrawSpriteDigit(parent, H_Maestro_001120a0(2),
                                value / 100 + 0xb, item->alpha,
                                item->x, item->y, depth);
            value %= 100;
        }
        if (value > 9 || rank != 0) {
            campDrawSpriteDigit(parent, H_Maestro_001120a0(2),
                                value / 10 + 0xb, item->alpha,
                                item->x + 16.0f, item->y,
                                depth);
        }
